entries[23806] = { ["name"] = "Schematic: Hyper-Vision Goggles", ["text"] = "Binds when picked up\nRequires Engineering (360)\nUse: Teaches you how to make Hyper-Vision Goggles.\nSell Price: 4\nHyper-Vision Goggles\nBinds when equipped\nHead Leather\n232 Armor\nDurability 60 / 60\nRequires Engineering (360)\nEquip: Improves hit rating by 23.\nEquip: Increases attack power by 84.\nUse: Increases your stealth detection for 15 sec. (2 Min Cooldown)\nSell Price: 3 17 74\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Nightseye (2), Large Prismatic Shard (2)" }
entries[23807] = { ["name"] = "Schematic: Adamantite Scope", ["text"] = "Requires Engineering (335)\nUse: Teaches you how to make an Adamantite Scope.\nSell Price: 1 50\nAdamantite Scope\nRequires Level 55\nUse: Attaches a permanent scope to a bow or gun that increases its damage by 10.\n\nAttaching this scope to a ranged weapon causes it to become soulbound.\nSell Price: 25\nRequires Adamantite Bar (8), Golden Draenite (2)" }
